from pathlib import Path
import base64,zlib,json,hashlib,subprocess,sys,zipfile
ROOT=Path(__file__).resolve().parents[1]
PAYLOAD=""
bundle=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
def git(*args):return subprocess.check_output(['git',*args],cwd=ROOT,text=True).strip()
def digest(data):return hashlib.sha256(data).hexdigest()
if git('remote','get-url','origin')!=bundle['origin']:raise SystemExit('Origin changed; stopping')
if git('rev-parse','HEAD')!=bundle['base_head']:raise SystemExit('HEAD changed; stopping')
problems=[]
for f in bundle['files']:
 p=ROOT/f['path'];data=f['text'].encode('utf-8')
 if ROOT not in p.resolve().parents:problems.append('Invalid path '+f['path']);continue
 if digest(data)!=f['sha256']:problems.append('Transfer hash '+f['path'])
 if p.exists():
  current=p.read_bytes()
  if digest(current)==f['sha256']:continue
  if f['baseline_sha256'] is None or (digest(current)!=f['baseline_sha256'] and digest(current.replace(b'\r\n',b'\n'))!=f['baseline_lf_sha256']):problems.append('Existing edits '+f['path'])
 elif f['baseline_sha256'] is not None:problems.append('Missing baseline '+f['path'])
if problems:print(json.dumps(problems,indent=2));raise SystemExit(2)
backup=ROOT/'tools/vehicle_fleet_preinstall_backup.zip'
if not backup.exists():
 with zipfile.ZipFile(backup,'w',zipfile.ZIP_DEFLATED) as z:
  for f in bundle['files']:
   p=ROOT/f['path']
   if p.exists():z.write(p,f['path'])
for f in bundle['files']:
 p=ROOT/f['path'];p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(f['text'].encode('utf-8'))
manifest={'baseline_head':bundle['base_head'],'source_paths':[f['path'] for f in bundle['files']],'status':'installed_pending_native_validation'}
(ROOT/'tools/vehicle_fleet_install_manifest.json').write_text(json.dumps(manifest,indent=2))
print('FLEET_INSTALLED',len(bundle['files']),flush=True)
subprocess.run([sys.executable,'tools/vehicle_fleet/build_catalog.py'],cwd=ROOT,check=True)
subprocess.run([sys.executable,'tools/vehicle_fleet/build_art.py'],cwd=ROOT,check=True)
try:import reportlab
except ImportError:subprocess.run([sys.executable,'-m','pip','install','reportlab'],check=True)
subprocess.run([sys.executable,'tools/vehicle_fleet/build_guide.py'],cwd=ROOT,check=True)
print('FLEET_NATIVE_BUILD_COMPLETE',flush=True)
